CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE SQL STABLE SECURITY INVOKER AS $safe$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $safe$;
