GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated;
CREATE TABLE public.n10a744_budgets (id uuid PRIMARY KEY,user_id uuid NOT NULL,note text);
ALTER TABLE public.n10a744_budgets ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.n10a744_budgets TO authenticated;
CREATE POLICY "budgets_delete_own" ON public.n10a744_budgets FOR DELETE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "budgets_insert_own" ON public.n10a744_budgets FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "budgets_select_own" ON public.n10a744_budgets FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "budgets_update_own" ON public.n10a744_budgets FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
